// Lettuce async: every call returns a RedisFuture at once
RedisClient client = RedisClient.create("redis://localhost:6379");
try (StatefulRedisConnection<String, String> conn = client.connect()) {
    RedisAsyncCommands<String, String> redis = conn.async();
    RedisFuture<String> status = redis.get("payment:42");
    RedisFuture<Long> auths = redis.incr("auths:today");
    // both commands are already on the wire; now wait for the replies
    System.out.println(status.get(1, TimeUnit.SECONDS) + " " + auths.get(1, TimeUnit.SECONDS));
} finally {
    client.shutdown();
}

