// Lettuce coroutines: calls suspend instead of returning futures
@OptIn(ExperimentalLettuceCoroutinesApi::class)
suspend fun printStatus(client: RedisClient) {
    client.connect().use { conn ->
        val redis = conn.coroutines()
        coroutineScope {
            val status = async { redis.get("payment:42") }
            val auths = async { redis.incr("auths:today") }
            println("${status.await()} ${auths.await()}")
        }
    }
}

