RedisClient redis = RedisClient.builder().hostAndPort("localhost", 6379).build();
ExecutorService pool = Executors.newFixedThreadPool(8);
for (int i = 0; i < 8_000; i++) {
    pool.submit(() -> {
        String v = redis.get("auths:today");                  // 1. read
        long n = v == null ? 0 : Long.parseLong(v);           // 2. add
        redis.set("auths:today", String.valueOf(n + 1));      // 3. write
    });
}
pool.shutdown();
pool.awaitTermination(1, TimeUnit.MINUTES);
System.out.println(redis.get("auths:today"));

