static final String BUSY = "local stop = os.clock() + tonumber(ARGV[1]) / 1000 while os.clock() < stop do end return 1";

static long timeGetDuringScript(RedisClient scripts, RedisClient app, String key, long millis) throws InterruptedException {
    CompletableFuture<Object> script = CompletableFuture.supplyAsync(
            () -> scripts.eval(BUSY, 0, String.valueOf(millis)));   // eval blocks a pool thread, not us
    Thread.sleep(200);                                               // head start: the script is running
    long t0 = System.nanoTime();
    app.get(key);                                                    // waits for the script to end
    long ms = (System.nanoTime() - t0) / 1_000_000;
    script.join();
    return ms;
}
